ALTER TABLE memberships DROP CONSTRAINT memberships_role_check;
ALTER TABLE memberships ADD CHECK(role IN ('owner','admin','member','finance','sales','operations','readonly'));
ALTER TABLE invitations DROP CONSTRAINT invitations_role_check;
ALTER TABLE invitations ADD CHECK(role IN ('admin','member','finance','sales','operations','readonly'));
-- Old policies list member as a tenant association, not as an action permission.
CREATE OR REPLACE FUNCTION app_has_role(cid text,uid text,roles text[]) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM public.memberships WHERE company_id=cid AND user_id=uid AND (role=ANY(roles) OR ('member'=ANY(roles) AND role IN ('sales','operations','readonly')))) $$;
CREATE TABLE operation_documents(id text PRIMARY KEY,company_id text NOT NULL REFERENCES companies(id),kind text NOT NULL,entity_key text NOT NULL,data jsonb NOT NULL,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,kind,entity_key));
CREATE TABLE record_versions(company_id text NOT NULL REFERENCES companies(id),record_id text NOT NULL REFERENCES records(id),version integer NOT NULL,data jsonb NOT NULL,user_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,record_id,version));
ALTER TABLE quotes ADD COLUMN version integer NOT NULL DEFAULT 1;
ALTER TABLE quotes ADD COLUMN approved_version integer;
ALTER TABLE quotes ADD COLUMN revises_id text REFERENCES quotes(id);
ALTER TABLE quotes ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();
UPDATE quotes SET approved_version=1 WHERE approved_at IS NOT NULL;
CREATE TABLE quote_versions(company_id text NOT NULL REFERENCES companies(id),quote_id text NOT NULL REFERENCES quotes(id),version integer NOT NULL,data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,quote_id,version));
INSERT INTO quote_versions SELECT company_id,id,version,data,created_at FROM quotes;
ALTER TABLE movements ADD COLUMN order_id text REFERENCES orders(id);
UPDATE movements m SET order_id=o.id FROM orders o WHERE split_part(m.idempotency_key,':',2)=o.id AND split_part(m.idempotency_key,':',1) IN ('reserve','consume') AND o.company_id=m.company_id;
ALTER TABLE orders ADD COLUMN completed_at timestamptz;
CREATE UNIQUE INDEX records_company_unique ON records(company_id,id);
CREATE UNIQUE INDEX purchase_items_company_unique ON purchase_list_items(company_id,id);
CREATE TABLE purchase_receipts(id text PRIMARY KEY,company_id text NOT NULL REFERENCES companies(id),list_item_id text NOT NULL,product_id text NOT NULL REFERENCES records(id),purchase_milli bigint NOT NULL CHECK(purchase_milli>0),stock_quantity integer NOT NULL CHECK(stock_quantity>0),note text NOT NULL,idempotency_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,idempotency_key),FOREIGN KEY(company_id,list_item_id) REFERENCES purchase_list_items(company_id,id));
CREATE TABLE financial_accounts(id text PRIMARY KEY,company_id text NOT NULL REFERENCES companies(id),name text NOT NULL,opening_cents bigint NOT NULL DEFAULT 0,active boolean NOT NULL DEFAULT true,UNIQUE(company_id,id));
ALTER TABLE ledger ADD COLUMN financial_kind text NOT NULL DEFAULT 'operating' CHECK(financial_kind IN ('operating','withdrawal'));
ALTER TABLE ledger ADD COLUMN account_id text;
ALTER TABLE ledger ADD COLUMN installment_group text;
ALTER TABLE ledger ADD COLUMN installment_number integer;
ALTER TABLE ledger ADD COLUMN recurrence_root text;
ALTER TABLE ledger ADD COLUMN recurrence_index integer NOT NULL DEFAULT 0;
ALTER TABLE ledger ADD FOREIGN KEY(company_id,account_id) REFERENCES financial_accounts(company_id,id);
CREATE UNIQUE INDEX ledger_recurrence_unique ON ledger(company_id,recurrence_root,due) WHERE recurrence_root IS NOT NULL;
ALTER TABLE payments ADD COLUMN account_id text;
ALTER TABLE payments ADD FOREIGN KEY(company_id,account_id) REFERENCES financial_accounts(company_id,id);
CREATE TABLE account_transfers(id text PRIMARY KEY,company_id text NOT NULL REFERENCES companies(id),from_id text NOT NULL,to_id text NOT NULL,amount_cents bigint NOT NULL CHECK(amount_cents>0),paid_at date NOT NULL,idempotency_key text NOT NULL,UNIQUE(company_id,idempotency_key),CHECK(from_id<>to_id),FOREIGN KEY(company_id,from_id) REFERENCES financial_accounts(company_id,id),FOREIGN KEY(company_id,to_id) REFERENCES financial_accounts(company_id,id));
CREATE TABLE import_jobs(id text PRIMARY KEY,company_id text NOT NULL REFERENCES companies(id),user_id text NOT NULL,kind text NOT NULL,status text NOT NULL DEFAULT 'ready',rows jsonb NOT NULL,cursor integer NOT NULL DEFAULT 0,result jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE imported_bank_rows(company_id text NOT NULL REFERENCES companies(id),fingerprint text NOT NULL,payment_id text REFERENCES payments(id),job_id text NOT NULL REFERENCES import_jobs(id),PRIMARY KEY(company_id,fingerprint));
CREATE TABLE ownership_transfers(id text PRIMARY KEY,company_id text NOT NULL REFERENCES companies(id),from_id text NOT NULL REFERENCES "user"(id),to_id text NOT NULL REFERENCES "user"(id),token_hash text UNIQUE NOT NULL,expires timestamptz NOT NULL,accepted_at timestamptz);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['operation_documents','record_versions','quote_versions','purchase_receipts','financial_accounts','account_transfers','import_jobs','imported_bank_rows','ownership_transfers'] LOOP
EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_isolation ON %I USING(company_id=current_setting(''app.company_id'',true) AND app_has_role(company_id,current_setting(''app.user_id'',true),ARRAY[''owner'',''admin'',''member'',''finance''])) WITH CHECK(company_id=current_setting(''app.company_id'',true) AND app_has_role(company_id,current_setting(''app.user_id'',true),ARRAY[''owner'',''admin'',''member'',''finance'']))',t);
END LOOP; END $$;
CREATE INDEX operation_kind ON operation_documents(company_id,kind);
CREATE INDEX records_schedule ON records(company_id,(data->>'due'),(data->>'assignee')) WHERE kind='appointments' AND deleted_at IS NULL;
